# ── 1. Filter in-scope programs (review_flag == 'review') ────
if isinstance(catalog, dict) and 'service_groups' in catalog:
    all_programs = []
    for group in catalog['service_groups']:
        all_programs.extend(group.get('programs', []))
elif isinstance(catalog, dict) and 'programs' in catalog:
    all_programs = catalog['programs']
else:
    all_programs = catalog

in_scope = [p for p in all_programs if p.get('review_flag') == 'review']

